'''
A starter file for testing a Flask app
Run with:
python -m unittest Tests/flask_tests.py
'''

from app import *
import unittest

class TestFlaskRetrievalDisplay(unittest.TestCase):
    def test_home(self):
        #sets up a special test app
        self.app = app.test_client() 
        #test app returns TestResponse object
        response = self.app.get('/', follow_redirects=True) 
        #TestResponse has webpage in .data
        self.assertEqual(b'Welcome to the homepage of water statistics!', response.data)
    
    def test_loc_year(self):
        #sets up a special test app
        self.app = app.test_client()

        response = self.app.get('/Afghanistan/2005/', follow_redirects=True) 
        self.assertEqual(b"[['Afghanistan', '2005', '6', '24 405', '23', '30', '4', '41', '25', '2.20', '64', '3', '25', '7', '1.66', '38', '4', '37', '21', '2.13', '', '12', '12', '19', '12', '0.83', '2', '32', '25', '54', '29', '25', '0.60', '23', '45', '15', '21', '21', '15', '0.79', '7', '35', 'Central and Southern Asia', 'Landlocked developing countries', 'Least developed countries', '-', 'Fragile or Extremely Fragile', 'Low income']]", response.data)

        response = self.app.get('/Sub-Saharan Africa/2019/', follow_redirects=True) 
        self.assertEqual(b"[['Sub-Saharan Africa', '2019', '1 096 034', '41', '48', '16', '24', '12', '0.95', '85', '9', '5', '1', '0.35', '63', '13', '16', '8', '0.93', '', 'Sub-Saharan Africa', '2019', '14', '14', '46', '22', '0.43', '21', '43', '51', '52', '66', '51', '0.40', '58', '35', '29', '29', '54', '34', '0.60', '36', '40', '195']]", response.data)

        response = self.app.get('/notacountry/2005/', follow_redirects=True) 
        self.assertEqual(b"Error: Country or region not found, please try again.", response.data)

        response = self.app.get('/Uganda/14/', follow_redirects=True) 
        self.assertEqual(b"Year outside range, please specify a year in the range 2000-2024.", response.data)

